#misteri{posizione:relativa;overflow:nascosto}
    #misteri .wrap{posizione:relativa;z-index:3}
    .myst-filterbar{display:flex;flex-wrap:wrap;gap:20px 28px;align-items:flex-end;margin-bottom:14px}
    .myst-filter-group{display:flex;direzione-flex:colonna;gap:9px;larghezza-min:0}
    .myst-filter-label{font-family:"Space Mono",ui-monospace,monospace;font-size:10px;letter-spacing:.24em;text-transform:uppercase;color:#d3a8c2}
    .myst-chip-row{display:flex;flex-wrap:wrap;gap:8px}
    .myst-chip{
      display:inline-flex;allinea-elementi:centro;gap:8px;cursore:puntatore;
      imbottitura: 9px 15px; raggio bordo: 999px;
      font-family:"Space Mono",ui-monospace,monospace;dimensione carattere:11px;
      spaziatura lettere: .14em;trasformazione testo: maiuscolo;colore:#f4e3d7;
      sfondo:rgba(20,7,44,.72);bordo:1px solido rgba(255,45,124,.3);
      transizione: trasforma la facilità di .15s, la facilità di box-ombra .2s, la facilità di colore del bordo .2s;
    }
    .myst-chip:hover{transform:translateY(-1px);border-color:rgba(255,45,124,.65);box-shadow:0 0 20px rgba(255,45,124,.25)}
    .myst-chip.attivo{
      background:var(--vi-grad-sunset,linear-gradient(90deg,#ff2d7c,#ff8a3d 52%,#ffd166));
      colore:var(--vi-ink,#33051c);colore-bordo:trasparente;peso-carattere:700;
      box-ombra:0 8px 22px -8px rgba(255,45,124,.65);
    }
    .myst-chip .myst-dot{larghezza:8px;altezza:8px;raggio-bordo:99px;flessione:0 0 auto}
    .myst-chip.active .myst-dot{contorno:1px solido rgba(51,5,28,.4)}
    .myst-dot--risolto{ background:linear-gradient(135deg,var(--vi-gold,#ffd166),#7ee08c)}
    .myst-dot--open{ background:var(--vi-pink,#ff2d7c);box-shadow:0 0 10px rgba(255,45,124,.8)}
    .myst-dot--lenda{ background:var(--vi-purple,#7b2ff7);box-shadow:0 0 10px rgba(123,47,247,.8)}
    .myst-dot--all{ background:#f4e3d7}
    .myst-chip piccolo{
      dimensione carattere: 10px; imbottitura: 2px 7px; raggio bordo: 99px; spaziatura lettere: .08em;
      sfondo:rgba(11,13,42,.55);colore:eredita;bordo:1px solido rgba(255,255,255,.18);
    }
    .myst-chip.active piccolo{sfondo:rgba(51,5,28,.22);colore-bordo:rgba(51,5,28,.3)}
    .myst-select{
      aspetto: nessuno;-webkit-aspetto: nessuno; cursore: puntatore; larghezza minima: 220px;
      imbottitura: 10px 38px 10px 14px; raggio bordo: 10px;
      font-family:"Space Mono",ui-monospace,monospace;dimensione carattere:12px;spaziatura lettere:.06em;
      colore:#fff5ec;sfondo:rgba(20,7,44,.72);bordo:1px solido rgba(255,45,124,.3);
      background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='12' Height='8' viewBox='0 0 12 8'><path d='M1 1l5 5 5-5' fill='none' ictus='%23ff2d7c' ictus-width='2' ictus-linecap='round'/></svg>");
      ripetizione dello sfondo: nessuna ripetizione; posizione dello sfondo: centro 14px a destra;
    }
    .myst-select:focus{outline:none;border-color:rgba(255,45,124,.7);box-shadow:0 0 18px rgba(255,45,124,.3)}
    .opzione myst-select{ background:#0b0d2a;color:#fff5ec}
    .myst-status-desc{
      margine: 0 0 18px; larghezza massima: 760px; colore: # d9c3d2; dimensione carattere: 14px; altezza linea: 1,6;
      bordo sinistro: 3px solido rgba (255,45,124,.55); imbottitura sinistra: 14px;
    }
    .myst-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(330px,1fr));gap:18px;align-items:start}
    .myst-card{display:flex;flex-direction:column;gap:0;padding:22px 22px 18px}
    .myst-card-top{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:14px}
    .myst-file-no{font-family:"Space Mono",ui-monospace,monospace;font-size:10px;letter-spacing:.22em;color:#b98ca9;text-transform:uppercase}
    .myst-stamp{transform:rotate(-2deg);font-size:10px;letter-spacing:.2em;padding:6px 13px}
    .myst-stamp--risolto{
      sfondo:gradiente lineare(90deg,var(--vi-gold,#ffd166),#7ee08c);
      colore:var(--vi-ink,#33051c);box-shadow:0 8px 22px -8px rgba(255,209,102,.7),0 0 20px rgba(126,224,140,.25);
    }
    .myst-stamp--open{color:var(--vi-pink,#ff2d7c);box-shadow:0 0 22px rgba(255,45,124,.4)}
    .myst-stamp--leggenda{
      colore:#cfa9ff;box-shadow:0 0 22px rgba(123,47,247,.45);
      sfondo:
        gradiente lineare(rgba(26,9,54,.9),rgba(26,9,54,.9)) riquadro di imbottitura,
        gradiente-lineare(90deg,var(--vi-purple,#7b2ff7),var(--vi-pink-2,#f152ff)) border-box;
    }
    .myst-chip-gioco{
      display:inline-flex;align-items:center;gap:6px;margin-bottom:10px;
      font-family:"Space Mono",ui-monospace,monospace;dimensione carattere:10px;
      spaziatura lettere: .18em;trasformazione testo:maiuscolo;colore:var(--vi-gold,#ffd166);
    }
    .myst-game-chip::before{content:"";larghezza:14px;altezza:1px;sfondo:var(--vi-gold,#ffd166);opacità:.7}
    .myst-card h3{margin:0 0 10px;font-size:20px;line-height:1.25;color:#fff5ec}
    .myst-desc{margin:0;color:#d9c8d4;font-size:14px;line-height:1.62}
    .myst-toggle{margin-top:16px;align-self:flex-start}
    .myst-body{margin-top:16px;padding-top:16px;border-top:1px tratteggiato rgba(255,45,124,.35)}
    .myst-evidence-etichetta{
      display:flessibile;allinea-elementi:centro;gap:8px;margine:16px 0 4px;
      font-family:"Space Mono",ui-monospace,monospace;dimensione carattere:10px;
      spaziatura lettere: .26em;trasformazione testo:maiuscolo;colore:#ff9ec4;
    }
    .myst-evidence-label:first-child{margin-top:0}
    .myst-evidence-label::after{contenuto:"";flex:1;altezza:1px;sfondo:rgba(255,45,124,.25)}
    .myst-list{list-style:none;margin:8px 0 0;padding:0}
    .myst-list li{display:flex;gap:10px;align-items:baseline;margin-bottom:8px;color:#e6d6dd;font-size:13.5px;line-height:1.6}
    .myst-idx{
      flex:0 0 auto;font-family:"Space Mono",ui-monospace,monospace;font-size:10px;
      spaziatura lettere: .08em;colore:var(--vi-gold,#ffd166);opacità:.85;larghezza minima:30px;
    }
    .myst-risoluzione{
      margin-top:18px;padding:14px 16px;border-radius:10px;
      bordo:1px tratteggiato rgba(255,209,102,.6);sfondo:rgba(255,209,102,.07);
    }
    .myst-section .myst-evidence-label{color:var(--vi-gold,#ffd166);margin-top:0}
    .myst-risoluzione .myst-evidence-label::after{ background:rgba(255,209,102,.35)}
    .myst-risoluzione p{margin:8px 0 0;color:#ffe9bd;font-size:13.5px;line-height:1.62}
    .myst-dove{
      display:flex;gap:10px;align-items:baseline;margin-top:16px;
      font-family:"Space Mono",ui-monospace,monospace;dimensione carattere:12px;
      colore:#cdb4c6;altezza della linea:1,55;
    }
    .myst-where svg{flex:0 0 auto;larghezza:14px;altezza:14px;transform:translateY(2px);colore:var(--vi-pink,#ff2d7c)}
    .mist-vuoto{
      imbottitura: 34px 26px; allineamento testo: centro; colore: # d3a8c2;
      font-family:"Space Mono",ui-monospace,monospace;dimensione carattere:13px;spaziatura lettere:.08em;
    }
    @media (larghezza massima: 760px){
      .myst-filterbar{direzione-flessione:colonna;allineamento-elementi:allungamento}
      .myst-select{larghezza:100%}
      .myst-grid{grid-template-columns:1fr}
      .myst-card{padding:18px 16px 16px}
    }
    @media (preferisce il movimento ridotto: ridurre){
      .myst-chip,.myst-chip:hover{transform:none;transizione:none}
    }
